import os
import re
import json

# Load grids
d = os.environ['RLM_SESSION_DIR']
t = open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')
G = {}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
    k, h, w = m[1], int(m[2]), int(m[3])
    rows = [r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(rows[i]) == w and all(x.isdigit() for x in rows[i]) for i in range(len(rows))):
        G[k] = [[int(x) for x in r] for r in rows]

input_demo = G['Demo pair 1 input']
output_demo = G['Demo pair 1 output']

# Find all non-zero cells in input that become 0 in output
print("Cells in Demo input that become 0:")
changed_cells = []
for r in range(15):
    for c in range(15):
        if input_demo[r][c] != 0:
            if output_demo[r][c] == 0:
                changed_cells.append((r, c))
                print(f"  ({r},{c}): {input_demo[r][c]} -> 0")

print(f"\nTotal cells changed to 0: {len(changed_cells)}")

# Now let's find all cells with value 3 in those changed rows/cols
print("\nLooking for 3s in rows 6-12 that become 0s:")
for r in range(6, 13):
    for c in range(15):
        if input_demo[r][c] == 3 and output_demo[r][c] == 0:
            print(f"  Row {r}, col {c}: 3 -> 0")

